insert into public.publications (id,owner_id,author_name,title,slug,abstract,content,area,level,keywords,license,status,views,downloads,created_at,published_at) values ('pub-educacao-ia','seed_nucleo','Núcleo Studiorium','Uso responsável de inteligência artificial em atividades escolares','uso-responsavel-ia-atividades-escolares','Um guia introdutório sobre autoria, verificação de fontes e uso responsável de ferramentas de inteligência artificial no estudo.','Ferramentas de inteligência artificial podem apoiar planejamento, revisão e exploração de ideias, mas o estudante continua responsável por compreender o conteúdo, conferir informações, declarar usos relevantes e preservar a própria autoria. Referências devem ser verificadas na fonte original antes da entrega.','Educação','Ensino médio',ARRAY['educação','IA','autoria']::text[],'CC BY-NC 4.0','published',418,87,'2026-08-12T14:00:00.000Z','2026-08-12T14:00:00.000Z') on conflict (id) do nothing;
insert into public.publications (id,owner_id,author_name,title,slug,abstract,content,area,level,keywords,license,status,views,downloads,created_at,published_at) values ('pub-metodologia','seed_nucleo','Núcleo Studiorium','Como transformar uma pergunta em problema de pesquisa','pergunta-em-problema-de-pesquisa','Notas práticas para delimitar tema, problema, hipótese e objetivos sem perder clareza metodológica.','Um problema de pesquisa útil é específico o bastante para orientar a investigação e aberto o bastante para exigir análise. Delimite público, contexto, período e variável principal; depois verifique se os dados necessários são acessíveis e se a pergunta cabe no tempo disponível.','Metodologia','Graduação',ARRAY['metodologia','pesquisa','TCC']::text[],'CC BY-NC 4.0','published',731,192,'2026-08-10T10:30:00.000Z','2026-08-10T10:30:00.000Z') on conflict (id) do nothing;
insert into public.publications (id,owner_id,author_name,title,slug,abstract,content,area,level,keywords,license,status,views,downloads,created_at,published_at) values ('pub-feira-ciencias','seed_helena','Helena Monte','Aprendizagem baseada em projetos em feiras de ciências escolares','aprendizagem-projetos-feiras-ciencias','Síntese de práticas para transformar feiras de ciências em processos de investigação, registro, comunicação e revisão de hipóteses.','Uma feira de ciências ganha valor formativo quando o projeto começa com uma pergunta investigável, registra tentativas e erros e termina com comunicação dos resultados. O foco não deve estar apenas no produto final, mas no percurso documentado pelo estudante.','Educação científica','Ensino fundamental',ARRAY['feira de ciências','projetos','aprendizagem']::text[],'CC BY 4.0','published',302,64,'2026-08-08T09:20:00.000Z','2026-08-08T09:20:00.000Z') on conflict (id) do nothing;
insert into public.discussions (id,author_id,author_name,title,body,category,status,created_at) values ('disc-ia-ensino','seed_nucleo','Núcleo Studiorium','A inteligência artificial pode melhorar o ensino?','Discussão aberta sobre usos responsáveis de IA em sala de aula, sem substituir autoria, leitura crítica e verificação de fontes.','Tecnologia','published','2026-08-16T18:15:00.000Z') on conflict (id) do nothing;
insert into public.discussions (id,author_id,author_name,title,body,category,status,created_at) values ('disc-tcc-dois-meses','seed_lucas','Lucas Alencar','Como estruturar a metodologia de um TCC em dois meses?','Troca de experiências sobre cronogramas realistas, definição de escopo, coleta de dados e escrita progressiva.','Metodologia','published','2026-08-15T11:00:00.000Z') on conflict (id) do nothing;
insert into public.discussions (id,author_id,author_name,title,body,category,status,created_at) values ('disc-feira-ciencias','seed_helena','Helena Monte','O que torna uma feira de ciências realmente investigativa?','Quais critérios ajudam a diferenciar um experimento demonstrativo de um projeto em que o estudante realmente formula, testa e revisa uma hipótese?','Educação','published','2026-08-14T16:40:00.000Z') on conflict (id) do nothing;
insert into public.replies (id,discussion_id,author_id,author_name,body,status,created_at) values ('reply-seed-1','disc-ia-ensino','seed_helena','Helena Monte','Um bom ponto de partida é declarar quando a ferramenta foi usada e conferir cada referência antes de entregar o trabalho.','published','2026-08-16T19:00:00.000Z') on conflict (id) do nothing;
insert into public.replies (id,discussion_id,author_id,author_name,body,status,created_at) values ('reply-seed-2','disc-tcc-dois-meses','seed_nucleo','Núcleo Studiorium','Com prazo curto, vale reduzir o escopo, definir uma pergunta central e escrever a metodologia ao mesmo tempo em que a coleta é organizada.','published','2026-08-15T13:20:00.000Z') on conflict (id) do nothing;
